public  class DBSubstance
    extends org.openscience.nmrshiftdb.om.BaseDBSubstance
    implements Persistent
{
	  /**
	   * Gets all keywords of this DBSpectrum separated by , or newline.
	   *
	   * @param  separatedByNewline  If true keywords are separated by \n else by ,.
	   * @return                     The keywords value.
	 * @throws DataSetException 
	   * @exception  Exception       Database problems.
	   */
	  public String getKeywords(boolean separatedByNewline) throws TorqueException, DataSetException {
	    StringBuffer keywords = new StringBuffer();
	    List<Record> result = DBKeywordPeer.executeQuery("select KEYWORD.KEYWORD from KEYWORD join SUBSTANCE_KEYWORD using (KEYWORD_ID ) where SUBSTANCE_ID ="+this.getSubstanceId());
	    for (int i = 0; i < result.size(); i++) {
	      if (separatedByNewline) {
	        keywords.append(result.get(i).getValue(1).asString() + "\n");
	      } else {
	        keywords.append(result.get(i).getValue(1).asString() + ";");
	      }
	    }
	    return (GeneralUtils.removeLastComma(keywords).toString());
	  }
}
